use vstd::prelude::*;

verus! {

fn ones(n: usize) -> (result: Vec<i8>)
    // No extra preconditions needed
    ensures
        // Exactly n entries
        result.len() == n,
    ensures
        // Each entry is 1
        forall |i: usize| i < n ==> result[i] == 1_i8,
    ensures
        // Any two entries are equal (follows from them both being 1)
        forall |i: usize, j: usize| i < n && j < n ==> result[i] == result[j],
    ensures
        // Each entry is positive
        forall |i: usize| i < n ==> result[i] > 0_i8
{
    let mut result: Vec<i8> = Vec::new();
    let mut i: usize = 0;
    while i < n
        invariant
            // The current length is exactly i
            result.len() == i,
        invariant
            // All entries so far are 1
            forall |j: usize| j < i ==> result[j] == 1_i8,
        decreases n - i,
    {
        result.push(1_i8);
        i = i + 1;
    }
    result
}

} // end verus!

